import numpy as np
def equation(t, P, params):
    a,b,c,g,d,h,e,k,m,n=params[0],params[1],params[2],params[3],params[4],params[5],params[6],params[7],params[8],params[9]
    H=np.abs(t)/(np.abs(d)+np.abs(t))
    return a*P + b*P**2 + c*P**3 + g*P*np.log(P) + m + h*H + e*P*H + n*P*np.exp(-k*t)
